function moveEntity(e,dx,dy){e.x=clamp(e.x+dx,63+e.r,977-e.r);e.y=clamp(e.y+dy,112+e.r,658-e.r);for(const o of obstacles){if(o.hp<=0)continue;let d=dist(e,o),min=e.r+o.r;if(d<min){const a=d>.01?angle(o,e):0;e.x=o.x+Math.cos(a)*min;e.y=o.y+Math.sin(a)*min}}}
function attack(){if(state!=='play'||player.attackCD>0||player.rollTime>0||player.block)return;const id=player.slots[player.slot],w=currentWeapon(),level=player.levels[id];if(player.st<5)return;player.st-=5;player.stDelay=.12;player.combo=player.comboTimer>0?(player.combo+1)%3:0;player.comboTimer=1.2;player.attackCD=w.rate/(player.rate*(1+level*.08));player.attackAnim=.2;weaponUse[id]++;const damage=w.dmg*player.damage*(1+level*.23)*(player.combo===2?1.35:1)*(boostTime>0?1.5:1)*(player.hp<player.maxhp*.3?1+player.lowDamage:1);const range=w.range*player.range*(1+level*.055);sfx('slash');if(id===6){projectiles.push({x:player.x+Math.cos(player.a)*15,y:player.y+Math.sin(player.a)*15,vx:Math.cos(player.a)*440,vy:Math.sin(player.a)*440,r:4,life:1.5,enemy:false,dmg:damage,kind:'arrow',pierce:level>=3?3:0,hit:new Set()});}else{swings.push({x:player.x,y:player.y,a:player.a,r:range,arc:w.arc,t:.16,max:.16,color:w.color});for(const e of enemies){if(e.hp<=0)continue;const a=angle(player,e);if(dist(player,e)<range+e.r&&Math.abs(diff(a,player.a))<w.arc/2+e.r/Math.max(20,dist(player,e))){const crit=Math.random()<player.crit+level*.025;hurtEnemy(e,damage*(crit?1.8:1),player.a,w.knock*player.knock,crit);if(id===5)e.root=level>=3?1.7:.75;if(id===7)e.burn=3.5;if(id===1&&level>=2)lightning(e,damage*.35);if(id===4&&level>=3){e.stun=.7;shake=7}if(id===0&&level>=3)player.hp=Math.min(player.maxhp,player.hp+1)}}for(const o of obstacles)if(o.hp<9999&&dist(player,o)<range+o.r&&Math.abs(diff(angle(player,o),player.a))<w.arc/2){o.hp-=damage;burst(o.x,o.y,8,'#b8905b',90);if(o.hp<=0){drops.push({x:o.x,y:o.y,type:Math.random()<.4?'health':'gold',value:15,life:50});sfx('hit')}}}}
function lightning(e,dmg){const target=enemies.filter(t=>t!==e&&t.hp>0&&dist(e,t)<150).sort((a,b)=>dist(e,a)-dist(e,b))[0];if(target){target.hp-=dmg;target.stun=.3;swings.push({bolt:true,x:e.x,y:e.y,tx:target.x,ty:target.y,t:.16,max:.16});if(target.hp<=0)killEnemy(target)}}
function hurtEnemy(e,dmg,a,knock=100,crit=false,unblockable=false){if(e.hp<=0)return;const facing=Math.abs(diff(angle(e,player),e.a))<1.1;const shield=(e.type===2||e.boss&&e.bossId===1||e.boss&&e.bossId===4&&e.cool>.6);if(shield&&facing&&e.stun<=0&&e.open<=0&&!unblockable){dmg*=e.boss&&e.bossId===1?.03:.18;burst(e.x,e.y,8,'#f1d28b',80);sfx('block');floatText(e.x,e.y-30,'BLOCK','#e5c686')}else{e.hit=.12;if(crit){hitstop=.035;shake=4;floatText(e.x,e.y-32,Math.ceil(dmg)+'!','#ffe39b')}else floatText(e.x,e.y-24,Math.ceil(dmg),'#f1e4c6');burst(e.x,e.y,crit?11:6,'#a04437',85);sfx('hit');if(player.bleed&&crit)e.bleed=4;if(player.element==='fire')e.burn=3;if(player.element==='poison')e.poison=4;if(player.element==='lightning'||Math.random()<player.lightning)lightning(e,dmg*.6)}e.hp-=dmg;e.kx+=Math.cos(a)*knock*(e.boss?.28:1);e.ky+=Math.sin(a)*knock*(e.boss?.28:1);if(e.hp<=0)killEnemy(e)}
function killEnemy(e){if(e.dead)return;e.dead=true;kills++;burst(e.x,e.y,16,e.boss?'#d7ad58':'#9d503b',100);drops.push({x:e.x,y:e.y,type:'gold',value:Math.round((e.boss?75:4+wave*.5)*(e.elite?2:1)*player.goldMulti),life:70});if(Math.random()<.09||e.boss)drops.push({x:e.x+15,y:e.y,type:'health',value:15,life:50});if(player.leech)player.hp=Math.min(player.maxhp,player.hp+player.leech);if(e.boss){bossKills++;shake=10;sfx('win');save.arena=Math.max(save.arena,Math.min(4,arenaIndex+1));persist();announce('BOSS BESIEGT',e.bossId===4?'DER CHAMPION IST GEFALLEN. DEIN RUHM BLEIBT.':'DIE MENGE FEIERT DICH')} }
function hurtPlayer(dmg,source,kind='hit'){if(state!=='play'||player.iframes>0||player.hp<=0)return;const a=source?angle(player,source):player.a,front=Math.abs(diff(a,player.a))<1.25;let blocked=false;if(player.block&&front&&player.st>8&&kind!=='floor'){if(player.blockTime<.2){player.st=Math.min(player.maxst,player.st+10);player.hp=Math.min(player.maxhp,player.hp+player.parryHeal);player.iframes=.22;const e=source;if(e?.hp){e.stun=1.6;e.open=2.3;e.wind=0;e.charge=0;e.cool=2}floatText(player.x,player.y-40,'PERFEKT!','#a9e6d2');burst(player.x,player.y,18,'#f9e3a3',150);shake=4;sfx('parry');return}player.st=Math.max(0,player.st-dmg*.95-8);player.stDelay=.65;dmg*=1-player.blockPower;blocked=true;sfx('block');burst(player.x,player.y,7,'#dfc181',60)}dmg=Math.max(blocked?1:2,dmg-player.armor);if(mode!=='training')player.hp-=dmg;player.iframes=.42;player.hit=.15;shake=Math.max(shake,blocked?2:5);if(!blocked){sfx('hit');burst(player.x,player.y,8,'#b44c42',80);player.kx-=Math.cos(a)*90;player.ky-=Math.sin(a)*90;if(kind==='poison')player.poison=3;if(kind==='fire')player.burn=2;if(kind==='net')player.slow=2}floatText(player.x,player.y-35,'−'+Math.ceil(dmg),blocked?'#ddd0ac':'#ff8a73');if(player.hp<=0){player.hp=0;state='dying';deathClock=1.1;clearInput();sfx('die')}}
function roll(){if(state!=='play'||player.rollTime>0||player.rolls<1||player.st<20)return;let x=input.jx+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y=input.jy+(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0),l=Math.hypot(x,y);if(l<.1){x=Math.cos(player.a);y=Math.sin(player.a);l=1}player.rollX=x/l;player.rollY=y/l;player.rollTime=.23+player.rollBonus;player.iframes=.19+player.rollBonus;player.rolls--;player.st-=20;player.stDelay=.6;player.block=false;player.rollRecharge=1.15;sfx('roll');burst(player.x,player.y,6,'#c4b48d',60)}
function special(){if(state!=='play'||player.specialCD>0)return;player.specialCD=player.specialMax*(player.skill===7?2.5:1);const id=player.skill,a=player.a,dmg=65*player.damage;shake=6;sfx('gong');if(id===6){slowTime=2;toast('ZEITLUPE · 2 SEKUNDEN')}else if(id===7){player.hp=Math.min(player.maxhp,player.hp+player.maxhp*.35);floatText(player.x,player.y-30,'HEILRUF','#a7e7aa');burst(player.x,player.y,25,'#a4d796',100)}else if(id===5){boostTime=7;player.st=player.maxst;toast('KAMPFSCHREI · +50 % SCHADEN · 7 SEK.');for(const e of enemies)if(dist(player,e)<200)e.stun=1}else if(id===3){projectiles.push({x:player.x,y:player.y,vx:Math.cos(a)*550,vy:Math.sin(a)*550,r:7,life:1.6,enemy:false,dmg:dmg*1.7,kind:'spear',pierce:8,hit:new Set()})}else if(id===2){moveEntity(player,Math.cos(a)*110,Math.sin(a)*110);player.iframes=.65;swings.push({ring:true,x:player.x,y:player.y,r:115,t:.45,max:.45,color:'#e8d2a0'});for(const e of enemies)if(dist(player,e)<115)hurtEnemy(e,dmg*1.4,angle(player,e),330,false,true)}else if(id===1){player.iframes=.6;moveEntity(player,Math.cos(a)*55,Math.sin(a)*55);for(const e of enemies)if(dist(player,e)<120&&Math.abs(diff(angle(player,e),a))<1.1){hurtEnemy(e,dmg,a,400,false,true);e.stun=2;e.open=2.5}swings.push({x:player.x,y:player.y,a,r:120,arc:2,t:.3,max:.3,color:'#97c8c4'})}else{swings.push({ring:true,x:player.x,y:player.y,r:id===4?150:120,t:.4,max:.4,color:id===4?'#f3a650':'#f1ddaa'});for(const e of enemies)if(dist(player,e)<(id===4?150:120)){hurtEnemy(e,dmg,angle(player,e),230,false,true);if(id===4)e.burn=6}if(id===4)hazards.push({x:player.x,y:player.y,r:125,type:'friendlyfire',life:4,clock:0})}burst(player.x,player.y,25,id===4?'#f2a854':'#e3cc8c',150)}
function enemyAttack(e,kind){e.attackKind=kind;e.windMax=e.boss?.88:e.type===7?.37:.65;e.windMax/=1+Math.min(.3,wave*.009);if(e.boss&&e.phase===2)e.windMax*=.8;e.wind=e.windMax;e.targetA=angle(e,player);e.tx=player.x;e.ty=player.y}
function resolveEnemyAttack(e){const a=e.targetA,kind=e.attackKind;e.cool=e.boss?1.15:rand(1.2,2.2);if(kind==='arrow'||kind==='net'||kind==='fireball'){projectiles.push({x:e.x,y:e.y,vx:Math.cos(a)*(kind==='net'?165:225),vy:Math.sin(a)*(kind==='net'?165:225),r:kind==='net'?9:5,life:4,enemy:true,dmg:e.dmg,kind,source:e})}else if(kind==='charge'){e.charge=.55;e.a=a;e.open=.9}else if(kind==='slam'){swings.push({ring:true,x:e.x,y:e.y,r:125,t:.4,max:.4,color:'#e39367'});if(dist(e,player)<125)hurtPlayer(e.dmg*1.3,e,'floor');for(let n=0;n<10;n++){let an=n*TAU/10;projectiles.push({x:e.x,y:e.y,vx:Math.cos(an)*155,vy:Math.sin(an)*155,r:7,life:1.3,enemy:true,dmg:e.dmg*.7,kind:'wave',source:e})}e.open=1.7;shake=4}else if(kind==='poisonrain'){for(let i=0;i<4;i++)hazards.push({x:clamp(e.tx+rand(-120,120),80,960),y:clamp(e.ty+rand(-110,110),130,640),r:35,type:'poison',life:6,clock:-.7});if(enemies.length<16){spawnEnemy(7);spawnEnemy(9)}e.open=1.2}else if(kind==='firering'){for(let i=0;i<9;i++){const an=i*TAU/9;hazards.push({x:clamp(e.x+Math.cos(an)*130,80,960),y:clamp(e.y+Math.sin(an)*130,130,640),r:32,type:'fire',life:5,clock:-.7})}hazards.push({x:e.tx,y:e.ty,r:50,type:'fire',life:4,clock:-.9});e.open=1.4}else{let reach=e.boss?92:e.type===1?100:e.type===6?78:53,arc=e.boss?2.3:1.5;if(dist(e,player)<reach+player.r&&Math.abs(diff(angle(e,player),a))<arc/2)hurtPlayer(e.dmg,e,e.type===9?'poison':e.boss&&e.bossId===3?'fire':'hit');swings.push({x:e.x,y:e.y,a,r:reach,arc,t:.15,max:.15,color:'#d48669'});if(e.boss&&e.bossId===1)e.open=1.4}sfx('slash')}
function updateEnemy(e,dt){e.age+=dt;e.hit=Math.max(0,e.hit-dt);e.open=Math.max(0,e.open-dt);e.stun=Math.max(0,e.stun-dt);e.root=Math.max(0,e.root-dt);e.cool-=dt;e.special-=dt;e.dotClock-=dt;for(const k of ['burn','poison','bleed']){if(e[k]>0){e[k]-=dt;if(e.dotClock<=0){e.hp-=(k==='burn'?7:k==='bleed'?9:5)*player.damage;burst(e.x,e.y-8,2,k==='burn'?'#f6a858':k==='poison'?'#a3b96a':'#a04a40',35)}}}if(e.dotClock<=0)e.dotClock=.55;if(e.hp<=0){killEnemy(e);return}moveEntity(e,e.kx*dt,e.ky*dt);e.kx*=Math.exp(-9*dt);e.ky*=Math.exp(-9*dt);if(e.stun>0)return;if(e.boss&&e.hp<e.maxhp*.5&&e.phase===1){e.phase=2;e.special=0;announce('PHASE II',e.bossId===4?'DER CHAMPION ZIEHT SEINE ZWEITE WAFFE':'JETZT WIRD ES ERNST');burst(e.x,e.y,20,'#ddae62',150)}if(e.charge>0){e.charge-=dt;moveEntity(e,Math.cos(e.a)*340*dt,Math.sin(e.a)*340*dt);if(dist(e,player)<e.r+player.r+8)hurtPlayer(e.dmg*1.2,e);burst(e.x,e.y,1,'#b4a078',35);return}if(e.wind>0){e.wind-=dt;if(e.wind<=0)resolveEnemyAttack(e);return}let d=dist(e,player),a=angle(e,player);e.a=a;if(e.boss&&e.special<=0){const kinds=['slam','charge','poisonrain','firering',e.phase===2?'slam':'charge'];enemyAttack(e,kinds[e.bossId]);e.special=e.phase===2?4.3:6.5;return}let ranged=[4,5,10].includes(e.type),reach=e.boss?83:e.type===1?90:e.type===6?67:46;if(e.cool<=0&&(ranged?d<380:d<reach)){enemyAttack(e,ranged?['arrow','net','fireball'][[4,5,10].indexOf(e.type)]:'melee');return}if(e.type===3&&d>120&&d<280&&e.cool<=0){enemyAttack(e,'charge');return}let vx=0,vy=0;if(ranged){const move=d>260?1:d<180?-1:0;vx=Math.cos(a)*move+Math.cos(a+Math.PI/2)*.35*e.side;vy=Math.sin(a)*move+Math.sin(a+Math.PI/2)*.35*e.side}else if(d>reach*.83){vx=Math.cos(a)+Math.cos(a+Math.PI/2)*.33*e.side;vy=Math.sin(a)+Math.sin(a+Math.PI/2)*.33*e.side}else if(e.cool>.3){vx=Math.cos(a+Math.PI/2)*e.side*.65;vy=Math.sin(a+Math.PI/2)*e.side*.65;if(e.type===1){vx-=Math.cos(a)*.5;vy-=Math.sin(a)*.5}}if(e.boss&&e.bossId===4&&e.hp<e.maxhp*.5&&e.cool>.5){vx*=1.7;vy*=1.7}let speed=e.speed*(e.root>0?.07:1)*(e.hp<e.maxhp*.3&&!ranged?1.12:1);moveEntity(e,vx*speed*dt,vy*speed*dt);e.move=Math.hypot(vx,vy);}
const upgradeDefs=[
 ['Schwere Klinge','+20 % Schaden','†',()=>player.damage*=1.2],['Leichte Schritte','+15 % Bewegungstempo','»',()=>player.speed=Math.min(295,player.speed*1.15)],['Zweite Chance','+1 Rollen-Ladung (max. 4)','↻',()=>{player.rollMax=Math.min(4,player.rollMax+1);player.rolls=player.rollMax}],['Schildwall','Block absorbiert 8 % mehr Schaden','▣',()=>player.blockPower=Math.min(.96,player.blockPower+.08)],['Offene Wunden','Kritische Treffer verursachen Blutung','‡',()=>player.bleed=true],['Wucht','+30 % Rückstoß','⊤',()=>player.knock*=1.3],['Perfekte Erholung','Perfekter Block heilt 6 Leben','✧',()=>player.parryHeal+=6],['Kampfmeditation','Spezialfähigkeit lädt 18 % schneller','✦',()=>player.specialMax=Math.max(5,player.specialMax*.82)],['Feuertaufe','Angriffe verbrennen Gegner','♨',()=>player.element='fire'],['Schlangengift','Angriffe vergiften Gegner','∿',()=>player.element='poison'],['Donnerschlag','Blitze springen auf nahe Gegner über','ϟ',()=>player.element='lightning'],['Gunst der Menge','+25 % Gold aus Gegnern','◈',()=>player.goldMulti*=1.25],['Heilkunst','Heiltränke wirken 40 % stärker','+',()=>player.healPower*=1.4],['Unbeugsam','+25 maximales Leben und Heilung','♥',()=>{player.maxhp+=25;player.hp=Math.min(player.maxhp,player.hp+40)}],['Schnelle Hände','+15 % Angriffstempo','↯',()=>player.rate*=1.15],['Adlerauge','+8 % kritische Trefferchance','⌖',()=>player.crit=Math.min(.8,player.crit+.08)],['Langer Arm','+12 % Waffenreichweite','↔',()=>player.range=Math.min(1.8,player.range*1.12)],['Zäher Kämpfer','+20 Ausdauer','▰',()=>{player.maxst+=20;player.st=player.maxst}]
];let offered=[];
function endWave(grant=true){if(state!=='play')return;state='upgrade';$('touch').hidden=true;$('bossHud').hidden=true;if(grant){for(const d of drops)if(d.type==='gold')collect(d);drops=drops.filter(d=>d.type!=='gold'&&d.life>0);player.gold+=15+wave*3;collected+=15+wave*3;player.hp=Math.min(player.maxhp,player.hp+Math.round(player.maxhp*.07));sfx('win');pendingShop=wave%3===0||wave%5===0;const pool=upgradeDefs.map((_,i)=>i).filter(i=>!(i===2&&player.rollMax>=4)&&!(i===4&&player.bleed));offered=pool.sort(()=>Math.random()-.5).slice(0,3);}panel('DIE MENGE JUBELT.',`Welle ${wave} überlebt · +${15+wave*3} Gold · Wähle deine Belohnung.`, `<div class="cards">${offered.map(i=>`<button class="card" data-do="upgrade:${i}"><span class="symbol">${upgradeDefs[i][2]}</span><strong>${upgradeDefs[i][0]}</strong><p>${upgradeDefs[i][1]}</p><span class="cost">WÄHLEN ↗</span></button>`).join('')}</div>`,btn('WAFFENSTÄNDER','armory'))}
const relicDefs=[['Löwenherz','+60 % Schaden unter 30 % Leben',()=>player.lowDamage=.6],['Kaisermünze','+50 % Gold',()=>player.goldMulti*=1.5],['Blutkelch','Heilt 2 Leben pro Kill',()=>player.leech+=2],['Schattenmantel','Längere Rolle und Unverwundbarkeit',()=>player.rollBonus=.1],['Donnerstein','25 % Chance auf Kettenblitz',()=>player.lightning=.25],['Gladiatorenkrone','+50 % Ruhm nach dem Run',()=>player.fameMulti*=1.5]];
function shop(){state='shop';const lvl=player.levels[player.slots[player.slot]];panel('DIE SCHMIEDE',`◈ ${player.gold} Gold · Rüste dich für die nächste Welle.`, `<div class="cards">${[['Trank','Heilt 45 % deines maximalen Lebens',30,'heal','+'],['Waffe verbessern',lvl>=3?'Legendäre Waffe erreicht':weapons[player.slots[player.slot]].names[lvl+1],45+lvl*45,'weapon','†'],['Schild verstärken','+5 % Blockstärke',45,'shield','▣'],['Rüstung kaufen','+2 Rüstung',55+player.armor*5,'armor','▰'],['Spezial trainieren','15 % kürzere Abklingzeit',65,'special','✦'],['Zufälliges Relikt','Ein einzigartiger Bonus für diesen Run',85,'relic','◈']].map(([n,d,c,id,icon])=>`<button class="card" data-do="purchase:${id}" ${player.gold<c||(id==='weapon'&&lvl>=3)||(id==='relic'&&player.relics.length===6)?'disabled':''}><span class="symbol">${icon}</span><strong>${n}</strong><p>${d}</p><span class="cost">◈ ${c} GOLD</span></button>`).join('')}</div>`,btn('WAFFENSTÄNDER','armory')+btn('WEITERKÄMPFEN','next','primary'))}
let armoryReturn='upgrade';function armory(){if(state!=='armory')armoryReturn=state;state='armory';panel('WAFFENSTÄNDER',`Wähle eine Waffe für Platz ${player.slot+1}. Wechsle unten mit 1–3 den Platz. Neue Funde kosten 35 Gold.`, `<div class="grid2">${weapons.map((w,i)=>`<button class="btn ${player.slots.includes(i)?'selected':''}" data-do="equip:${i}" ${!save.unlocked.includes(i)&&player.gold<35?'disabled':''}>${w.icon} ${w.name}${player.slots.includes(i)?' ✓':!save.unlocked.includes(i)?' · ◈ 35':''}</button>`).join('')}</div>`,btn('ZURÜCK','backarmory'))}
function purchase(id){const lvl=player.levels[player.slots[player.slot]],cost={heal:30,weapon:45+lvl*45,shield:45,armor:55+player.armor*5,special:65,relic:85}[id];if(player.gold<cost)return;if(id==='weapon'&&lvl>=3)return;player.gold-=cost;if(id==='heal')player.hp=Math.min(player.maxhp,player.hp+player.maxhp*.45*player.healPower);if(id==='weapon')player.levels[player.slots[player.slot]]++;if(id==='shield')player.blockPower=Math.min(.96,player.blockPower+.05);if(id==='armor')player.armor+=2;if(id==='special')player.specialMax=Math.max(5,player.specialMax*.85);if(id==='relic'){const possible=relicDefs.map((_,i)=>i).filter(i=>!player.relics.includes(i));if(!possible.length){player.gold+=cost;return}const n=pick(possible);player.relics.push(n);relicDefs[n][2]();toast(relicDefs[n][0]+' · '+relicDefs[n][1])}sfx('gold');updateLoadout();shop()}
